def _preencher_cobranca_do_historico(apps, schema_editor):
    """Recupera a cobranca das mensagens ja enviadas pela Meta.

    O webhook guarda cada evento de status em metadata_envio['meta_webhook']; o
    objeto `pricing` vem em um deles (sent, delivered ou read).
    """
    from django.utils.dateparse import parse_datetime

    MensagemContato = apps.get_model('acolhimento', 'MensagemContato')
    atualizar = []
    for mensagem in MensagemContato.objects.filter(metadata_envio__has_key='meta_webhook').iterator():
        historico = (mensagem.metadata_envio or {}).get('meta_webhook') or []
        if not isinstance(historico, list):
            historico = [historico]
        for item in historico:
            if not isinstance(item, dict):
                continue
            pricing = (item.get('evento') or {}).get('pricing')
            if not isinstance(pricing, dict):
                continue
            tipo = str(pricing.get('type') or '').strip().lower()
            if not tipo and pricing.get('billable') is not None:
                tipo = 'regular' if pricing.get('billable') else 'free_customer_service'
            mensagem.cobranca_categoria = str(pricing.get('category') or '').strip().lower()
            mensagem.cobranca_tipo = tipo
            mensagem.cobranca_modelo = str(pricing.get('pricing_model') or '').strip().upper()[:10]
            mensagem.cobranca_registrada_em = parse_datetime(str(item.get('received_at') or ''))
            atualizar.append(mensagem)
            break
    MensagemContato.objects.bulk_update(
        atualizar,
        ['cobranca_categoria', 'cobranca_tipo', 'cobranca_modelo', 'cobranca_registrada_em'],
        batch_size=200,
    )


